INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ainergiz/xfeed/new-issue', 'community', 'ainergiz', 'xfeed', 'ainergiz/xfeed', 'new-issue', 0, 0, 46, '2026-03-02T01:56:11.120Z', '2026-03-02T03:39:09.097Z', '1cbafc7994897da52899011b9091ef8ec6d0a1502be46322a8539242ea64baa8', '{"id":"ainergiz/xfeed/new-issue","name":"new-issue","description":{"zh":"新issue AI智能工具提供了基于终端的X应用接口，简化开发流程","ja":"新規issue AIエージェントは、TerminalベースのXアプリケーションインターフェースを提供し、開発プロセスを簡素化します","ko":"새로운 이슈 AI 에이전트는 터미널 기반의 X 애플리케이션 인터페이스를 제공하여 개발 프로세스를 간소화합니다","es":"new-issue es una interfaz de terminal para aplicaciones, que permite a los desarrolladores interactuar con herramientas de AI de manera eficiente","fr":"new-issue est une interface de terminal pour les applications, qui permet aux développeurs d''interagir avec les outils d''IA de manière efficace","de":"new-issue ist eine Terminal-Oberfläche für Anwendungen, die es Entwicklern ermöglicht, mit KI-Tools auf effiziente Weise zu interagieren","pt":"O new-issue é uma interface de terminal para tudo em um aplicativo, permitindo que os desenvolvedores acessem e gerenciem suas ferramentas de forma eficiente","ru":"ИИ Агент new-issue представляет собой терминальный интерфейс для всего в одном приложении, позволяя разработчикам доступ и управление инструментами эффективно","ar":"يعتبر new-issue واجهة طرفية لجميع التطبيقات، مما يسمح للمطورين بالوصول إلى أدواتهم وإدارتها بفعالية","en":"Terminal based interface for X, everything app"},"seo":{"title":{"zh":"新issue AI智能工具 - 基于终端的X应用接口","ja":"新規issue AIエージェント - TerminalベースのXアプリケーションインターフェース","ko":"새로운 이슈 AI 에이전트 - 터미널 기반 X 애플리케이션 인터페이스","es":"Herramientas de AI: Interfaz de Terminal para new-issue","fr":"Outils d''IA: Interface Terminal pour new-issue","de":"KI-Tools: Terminal-Oberfläche für new-issue","pt":"Ferramentas de IA: new-issue, Interface de Terminal","ru":"ИИ Агенты: new-issue, Терминальн